// The home screen's backdrop, inlined as a data URI.
// It HAS to be inlined: config.xml's CSP allows img-src 'self' data: blob: file: and not https,
// so a background fetched from a URL is blocked by the TV. Inlining also means it still shows
// with no network. Swap the art by replacing this one string.
//
// Current art: Ratropolis canal at night, supplied by Aaron, cropped to 16:9, resized to
// 1920x1080 and saved as art/bg-ratropolis.jpg in this repo. No text is baked into it --
// the clock, date and weather are all live DOM on top.
window.HOME_THEME = {
  background: 'data:image/jpeg;base64,'
};
